import React, { useEffect, useState } from "react";
import { PairingPage } from "./PairingPage";
import { RemoteProjectSummary, RemoteSessionItem, RemoteSessionList } from "./RemoteSessionList";
import { RemoteTerminal } from "./RemoteTerminal";

const TOKEN_KEY = "ferryx_remote_token";
const LEGACY_TOKEN_KEY = "rorca_remote_token";

export const RemoteApp: React.FC = () => {
  const [token, setToken] = useState<string | null>(
    () => localStorage.getItem(TOKEN_KEY) ?? localStorage.getItem(LEGACY_TOKEN_KEY)
  );
  const [sessions, setSessions] = useState<RemoteSessionItem[]>([]);
  const [projects, setProjects] = useState<RemoteProjectSummary[]>([]);
  const [activeWorkspaceId, setActiveWorkspaceId] = useState<string | null>(null);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);

  useEffect(() => {
    // Check fragment #pair=<code >
    const hash = window.location.hash;
    if (hash.startsWith("#pair=")) {
      const code = hash.replace("#pair=", "");
      fetch("/api/v1/pair/exchange", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          code,
          deviceName: navigator.userAgent.includes("Mobile") ? "Mobile Device" : "Browser Device",
        }),
      })
        .then((res) => res.json())
        .then((data) => {
          if (data.token) {
            handlePaired(data.token);
            window.location.hash = "";
          }
        })
        .catch(() => {});
    }
  }, []);

  const handlePaired = (newToken: string) => {
    localStorage.setItem(TOKEN_KEY, newToken);
    localStorage.removeItem(LEGACY_TOKEN_KEY);
    setToken(newToken);
  };

  // Fetches sessions together with their owning projects/active workspace in
  // one atomic call, so the session list and its hierarchy metadata (used to
  // group sessions by project/worktree) never observe two different points in
  // time from separate requests racing each other.
  const refreshWorkspace = async () => {
    if (!token) return;
    try {
      const res = await fetch(`/api/v1/workspace/state?token=${encodeURIComponent(token)}`);
      if (!res.ok) {
        localStorage.removeItem(TOKEN_KEY);
        localStorage.removeItem(LEGACY_TOKEN_KEY);
        setToken(null);
        return;
      }
      const data = await res.json();
      setSessions(data.sessions ?? []);
      setProjects(data.projects ?? []);
      setActiveWorkspaceId(data.activeWorkspaceId ?? null);
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    if (token) {
      refreshWorkspace();
    }
  }, [token]);

  if (!token) {
    return <PairingPage onPaired={handlePaired} />;
  }

  if (activeSessionId) {
    return (
      <RemoteTerminal
        sessionId={activeSessionId}
        token={token}
        onBack={() => {
          setActiveSessionId(null);
          // Re-fetch workspace state on return so sessions/worktrees created or
          // destroyed while attached (e.g. the user closed the shell, or the
          // desktop app spawned/removed worktrees) are reflected immediately.
          refreshWorkspace();
        }}
      />
    );
  }

  return (
    <div className="flex min-h-screen flex-col bg-background text-foreground">
      <header className="flex items-center justify-between border-b border-border bg-card px-4 py-3">
        <h1 className="text-base font-bold flex items-center gap-2">
          🦀 Ferryx Remote
        </h1>
        <button
          onClick={() => {
            localStorage.removeItem(TOKEN_KEY);
            localStorage.removeItem(LEGACY_TOKEN_KEY);
            setToken(null);
          }}
          className="text-xs text-muted-foreground hover:text-foreground"
        >
          Disconnect
        </button>
      </header>

      <main className="flex-1 p-4">
        <RemoteSessionList
          sessions={sessions}
          onSelect={(id) => setActiveSessionId(id)}
          onRefresh={refreshWorkspace}
          projects={projects}
          activeWorkspaceId={activeWorkspaceId}
        />
      </main>
    </div>
  );
};

import {
  ChevronRight,
  FolderGit2,
  GitBranch,
  Laptop,
  RefreshCw,
  Terminal as TerminalIcon,
} from "lucide-react";
import React, { useMemo, useState } from "react";

export type RemoteSessionItem = {
  sessionId: string;
  title?: string | null;
  workspaceId?: string | null;
  worktreeLabel?: string | null;
  running: boolean;
};

/** Minimal project identity needed to place a session under its owning project. */
export type RemoteProjectSummary = {
  workspaceId: string;
  repoRoot?: string | null;
};

export type RemoteHierarchyState = {
  sessions: RemoteSessionItem[];
  projects?: RemoteProjectSummary[] | null;
  activeWorkspaceId?: string | null;
};

export type WorktreeSessionGroup = {
  /** Internal, render-stable identity. Never displayed. */
  key: string;
  /** Safe-to-display label. Never a raw local absolute path. */
  label: string;
  sessions: RemoteSessionItem[];
};

export type ProjectSessionGroup = {
  /** Internal, render-stable identity. Never displayed. */
  key: string;
  /** Safe-to-display label. Never a raw local absolute path. */
  label: string;
  isActive: boolean;
  isUngrouped: boolean;
  worktreeGroups: WorktreeSessionGroup[];
};

const UNGROUPED_PROJECT_KEY = "__ungrouped-project__";
const UNGROUPED_WORKTREE_LABEL = "Ungrouped";

/**
 * Groups sessions into project -> worktree buckets for accordion rendering.
 *
 * - Sessions whose `workspaceId` doesn't match a known project (or is missing
 *   entirely, e.g. sessions-only/non-workspace mode) fall into a synthetic
 *   "Ungrouped" project bucket instead of being dropped or crashing the tree.
 * - Worktree group keys are namespaced by their owning project key so two
 *   projects that happen to share a worktree label (including the literal
 *   "Ungrouped" fallback) never collapse into a single group.
 * - Display labels only ever come from `workspaceId`/`worktreeLabel`, both of
 *   which the backend already derives as short, human-readable strings
 *   (branch names or single path segments) -- never a raw local filesystem
 *   path -- so we never need to (and never do) render one here.
 */
export function buildHierarchy(state: RemoteHierarchyState): ProjectSessionGroup[] {
  const projects = state.projects ?? [];
  const knownProjectIds = new Set(projects.map((p) => p.workspaceId));
  const projectOrder = [...projects.map((p) => p.workspaceId), UNGROUPED_PROJECT_KEY];

  type MutableProjectGroup = {
    label: string;
    isActive: boolean;
    isUngrouped: boolean;
    worktrees: Map<string, WorktreeSessionGroup>;
  };
  const projectGroups = new Map<string, MutableProjectGroup>();

  const ensureProject = (key: string): MutableProjectGroup => {
    let group = projectGroups.get(key);
    if (!group) {
      const isUngrouped = key === UNGROUPED_PROJECT_KEY;
      group = {
        label: isUngrouped ? "Ungrouped" : key,
        isActive: !isUngrouped && key === state.activeWorkspaceId,
        isUngrouped,
        worktrees: new Map(),
      };
      projectGroups.set(key, group);
    }
    return group;
  };

  for (const session of state.sessions) {
    const projectKey =
      session.workspaceId && knownProjectIds.has(session.workspaceId)
        ? session.workspaceId
        : UNGROUPED_PROJECT_KEY;
    const project = ensureProject(projectKey);

    const worktreeLabel = session.worktreeLabel?.trim() || UNGROUPED_WORKTREE_LABEL;
    const worktreeKey = `${projectKey}::${worktreeLabel}`;
    let worktreeGroup = project.worktrees.get(worktreeKey);
    if (!worktreeGroup) {
      worktreeGroup = { key: worktreeKey, label: worktreeLabel, sessions: [] };
      project.worktrees.set(worktreeKey, worktreeGroup);
    }
    worktreeGroup.sessions.push(session);
  }

  const result: ProjectSessionGroup[] = [];
  for (const key of projectOrder) {
    const group = projectGroups.get(key);
    if (!group || group.worktrees.size === 0) continue;
    result.push({
      key,
      label: group.label,
      isActive: group.isActive,
      isUngrouped: group.isUngrouped,
      worktreeGroups: [...group.worktrees.values()],
    });
  }
  return result;
}

type RemoteSessionListProps = {
  sessions: RemoteSessionItem[];
  onSelect: (sessionId: string) => void;
  onRefresh: () => void;
  projects?: RemoteProjectSummary[] | null;
  activeWorkspaceId?: string | null;
};

const SessionCard: React.FC<{ session: RemoteSessionItem; onSelect: (id: string) => void }> = ({
  session: s,
  onSelect,
}) => (
  <div
    key={s.sessionId}
    onClick={() => onSelect(s.sessionId)}
    className="group relative flex cursor-pointer items-center justify-between rounded-xl border border-border bg-card p-3.5 transition-all hover:border-primary/50 hover:bg-accent active:scale-[0.99]"
  >
    <div className="flex items-start gap-3 min-w-0">
      <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-border bg-muted text-muted-foreground transition-colors group-hover:border-primary/30 group-hover:text-primary">
        <TerminalIcon size={16} />
      </div>
      <div className="min-w-0 space-y-0.5">
        <div className="flex items-center gap-2">
          <span className="truncate font-mono text-xs font-semibold text-foreground">
            {s.title || `Terminal (${s.sessionId.substring(0, 8)})`}
          </span>
          <span className="inline-flex items-center gap-1 rounded border border-status-success/20 bg-status-success/10 px-1.5 py-0.5 text-[10px] font-medium text-status-success">
            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-status-success" />
            Running
          </span>
        </div>
        <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
          <span className="flex items-center gap-1 font-mono">
            <GitBranch size={12} />
            {s.worktreeLabel || "main"}
          </span>
          <span>•</span>
          <span className="font-mono text-[10px] text-muted-foreground/75">
            ID: {s.sessionId.substring(0, 8)}
          </span>
        </div>
      </div>
    </div>

    <div className="shrink-0 pl-3">
      <span className="inline-flex items-center justify-center rounded-lg bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground shadow-sm transition-colors group-hover:bg-primary/90">
        Attach
      </span>
    </div>
  </div>
);

const WorktreeGroupSection: React.FC<{
  group: WorktreeSessionGroup;
  showHeader: boolean;
  onSelect: (id: string) => void;
}> = ({ group, showHeader, onSelect }) => {
  const [expanded, setExpanded] = useState(true);
  const panelId = `remote-worktree-panel-${group.key.replace(/[^a-zA-Z0-9_-]/g, "_")}`;

  return (
    <div className="space-y-2">
      {showHeader ? (
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="flex w-full items-center gap-1.5 text-left text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronRight
            aria-hidden="true"
            size={12}
            className={`transition-transform shrink-0 ${expanded ? "rotate-90" : ""}`}
          />
          <GitBranch size={12} className="shrink-0" />
          <span className="truncate">{group.label}</span>
          <span className="text-muted-foreground/75">({group.sessions.length})</span>
        </button>
      ) : null}

      {expanded ? (
        <div id={panelId} className="grid gap-2.5">
          {group.sessions.map((s) => (
            <SessionCard key={s.sessionId} session={s} onSelect={onSelect} />
          ))}
        </div>
      ) : null}
    </div>
  );
};

const ProjectGroupSection: React.FC<{
  group: ProjectSessionGroup;
  showHeader: boolean;
  onSelect: (id: string) => void;
}> = ({ group, showHeader, onSelect }) => {
  const [expanded, setExpanded] = useState(true);
  const panelId = `remote-project-panel-${group.key.replace(/[^a-zA-Z0-9_-]/g, "_")}`;
  const showWorktreeHeaders = group.worktreeGroups.length > 1;

  return (
    <div className="space-y-2.5">
      {showHeader ? (
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="flex w-full items-center gap-1.5 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronRight
            aria-hidden="true"
            size={13}
            className={`transition-transform shrink-0 ${expanded ? "rotate-90" : ""}`}
          />
          <FolderGit2 size={13} className="shrink-0" />
          <span className="truncate normal-case">{group.label}</span>
          {group.isActive ? (
            <span className="normal-case text-[10px] font-medium text-primary">active</span>
          ) : null}
        </button>
      ) : null}

      {expanded ? (
        <div id={panelId} className="space-y-3 pl-1">
          {group.worktreeGroups.map((wg) => (
            <WorktreeGroupSection
              key={wg.key}
              group={wg}
              showHeader={showWorktreeHeaders}
              onSelect={onSelect}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
};

export const RemoteSessionList: React.FC<RemoteSessionListProps> = ({
  sessions,
  onSelect,
  onRefresh,
  projects,
  activeWorkspaceId,
}) => {
  const hierarchy = useMemo(
    () => buildHierarchy({ sessions, projects, activeWorkspaceId }),
    [sessions, projects, activeWorkspaceId]
  );
  const showProjectHeaders = hierarchy.length > 1;

  return (
    <div className="max-w-xl mx-auto p-4 space-y-6">
      {/* Workspace Header Overview */}
      <div className="flex items-center justify-between border-b border-border pb-3">
        <div className="flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg border border-primary/20 bg-primary/10 text-primary">
            <Laptop size={18} />
          </div>
          <div>
            <h2 className="text-sm font-semibold tracking-tight text-foreground">
              Desktop Workspace
            </h2>
            <p className="text-[11px] text-muted-foreground">
              Connected to Ferryx native engine
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={onRefresh}
          className="flex items-center gap-1.5 rounded border border-border bg-secondary px-2.5 py-1.5 text-xs font-medium text-secondary-foreground transition-all hover:bg-accent active:scale-95"
        >
          <RefreshCw size={13} />
          Refresh
        </button>
      </div>

      {/* Terminal Sessions Section */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <TerminalIcon size={15} className="text-muted-foreground" />
            <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              Active Terminals ({sessions.length})
            </h3>
          </div>
        </div>

        {sessions.length === 0 ? (
          <div className="space-y-3 rounded-xl border border-border bg-card px-4 py-12 text-center">
            <div className="mx-auto flex h-10 w-10 items-center justify-center rounded-full bg-muted text-muted-foreground">
              <TerminalIcon size={20} />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium text-foreground">No active terminals</p>
              <p className="text-xs text-muted-foreground">
                Open a terminal in your desktop Ferryx app to attach.
              </p>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {hierarchy.map((group) => (
              <ProjectGroupSection
                key={group.key}
                group={group}
                showHeader={showProjectHeaders}
                onSelect={onSelect}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import type { FitAddon } from "@xterm/addon-fit";
import type { Terminal } from "@xterm/xterm";
import React, { useEffect, useRef, useState } from "react";
import { MobileKeyDock } from "../components/MobileKeyDock";
import { attachWebglRenderer, loadTerminalAssets } from "../lib/terminalRenderer";
import { applyTerminalSettings, useTerminalSettings } from "../lib/terminalSettings";

type RemoteTerminalProps = {
  sessionId: string;
  token: string;
  title?: string;
  onBack: () => void;
};

export const RemoteTerminal: React.FC<RemoteTerminalProps> = ({
  sessionId,
  token,
  title,
  onBack,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const termRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const [connected, setConnected] = useState(false);
  const { settings, refreshNativePreferences } = useTerminalSettings();
  const settingsRef = useRef(settings);

  settingsRef.current = settings;

  useEffect(() => {
    void refreshNativePreferences();
  }, [refreshNativePreferences]);

  useEffect(() => {
    if (!containerRef.current) return;

    let terminalInstance: Terminal | null = null;
    let cleanupWebgl: (() => void) | null = null;
    let onDataDisposable: { dispose: () => void } | null = null;
    let isDisposed = false;
    const abortController = new AbortController();

    loadTerminalAssets()
      .then(async ({ Terminal: TerminalCtor, FitAddon: FitAddonCtor }) => {
        if (isDisposed || !containerRef.current) return;

        const term = new TerminalCtor({
          cursorBlink: true,
          fontFamily: settingsRef.current.fontFamily,
          fontSize: settingsRef.current.fontSize,
          macOptionIsMeta: settingsRef.current.macosOptionAsAlt,
          scrollback: settingsRef.current.scrollback,
          cursorStyle: settingsRef.current.cursorStyle,
          allowProposedApi: false,
          customGlyphs: true,
          convertEol: true,
          lineHeight: 1.0,
          letterSpacing: 0,
          theme: {
            background: settingsRef.current.theme.background,
            foreground: settingsRef.current.theme.foreground,
            cursor: settingsRef.current.theme.cursor,
            cursorAccent: settingsRef.current.theme.cursorAccent,
            selectionBackground: settingsRef.current.theme.selectionBackground,
            selectionForeground: settingsRef.current.theme.selectionForeground,
            black: settingsRef.current.theme.black,
            red: settingsRef.current.theme.red,
            green: settingsRef.current.theme.green,
            yellow: settingsRef.current.theme.yellow,
            blue: settingsRef.current.theme.blue,
            magenta: settingsRef.current.theme.magenta,
            cyan: settingsRef.current.theme.cyan,
            white: settingsRef.current.theme.white,
            brightBlack: settingsRef.current.theme.brightBlack,
            brightRed: settingsRef.current.theme.brightRed,
            brightGreen: settingsRef.current.theme.brightGreen,
            brightYellow: settingsRef.current.theme.brightYellow,
            brightBlue: settingsRef.current.theme.brightBlue,
            brightMagenta: settingsRef.current.theme.brightMagenta,
            brightCyan: settingsRef.current.theme.brightCyan,
            brightWhite: settingsRef.current.theme.brightWhite,
            extendedAnsi: settingsRef.current.theme.extendedAnsi,
          },
          allowTransparency: true,
        });

        const fitAddon = new FitAddonCtor();
        term.loadAddon(fitAddon);
        term.open(containerRef.current);
        cleanupWebgl = await attachWebglRenderer(term, abortController.signal);

        if (isDisposed) {
          term.dispose();
          cleanupWebgl?.();
          return;
        }

        // Defer initial fit to requestAnimationFrame with dimension guard
        requestAnimationFrame(() => {
          if (containerRef.current && containerRef.current.clientWidth > 0) {
            fitAddon.fit();
          }
        });

        termRef.current = term;
        fitRef.current = fitAddon;
        terminalInstance = term;

        const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
        const wsUrl = `${protocol}//${window.location.host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(token)}`;

        const ws = new WebSocket(wsUrl);
        ws.binaryType = "arraybuffer";
        wsRef.current = ws;

        ws.onopen = () => {
          setConnected(true);
          if (containerRef.current && containerRef.current.clientWidth > 0) {
            fitAddon.fit();
            ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
          }
        };

        ws.onclose = () => {
          setConnected(false);
        };

        ws.onmessage = (event) => {
          if (typeof event.data === "string") {
            term.write(event.data);
          } else {
            term.write(new Uint8Array(event.data));
          }
        };

        onDataDisposable = term.onData((data) => {
          if (ws.readyState === WebSocket.OPEN) {
            ws.send(new TextEncoder().encode(data));
          }
        });
      })
      .catch(() => {});

    // Coalesced viewport adaptation using requestAnimationFrame
    let rAfId: number | null = null;
    const scheduleResize = () => {
      if (rAfId !== null) cancelAnimationFrame(rAfId);
      rAfId = requestAnimationFrame(() => {
        rAfId = null;
        if (window.visualViewport && rootRef.current) {
          rootRef.current.style.height = `${window.visualViewport.height}px`;
        }
        if (fitRef.current && containerRef.current && containerRef.current.clientWidth > 0 && termRef.current) {
          fitRef.current.fit();
          if (wsRef.current?.readyState === WebSocket.OPEN) {
            wsRef.current.send(
              JSON.stringify({
                type: "resize",
                cols: termRef.current.cols,
                rows: termRef.current.rows,
              })
            );
          }
        }
      });
    };

    window.addEventListener("resize", scheduleResize);
    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", scheduleResize);
    }

    return () => {
      isDisposed = true;
      abortController.abort();
      if (rAfId !== null) cancelAnimationFrame(rAfId);
      window.removeEventListener("resize", scheduleResize);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener("resize", scheduleResize);
      }
      if (onDataDisposable) {
        onDataDisposable.dispose();
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
      if (cleanupWebgl) {
        cleanupWebgl();
      }
      if (terminalInstance) {
        terminalInstance.dispose();
      }
    };
  }, [sessionId, token]);

  // Synchronize settings changes dynamically
  useEffect(() => {
    if (termRef.current) {
      applyTerminalSettings(termRef.current, settings);
      fitRef.current?.fit();
    }
  }, [settings]);

  const sendKey = (key: string) => {
    const ws = wsRef.current;
    if (!ws || ws.readyState !== WebSocket.OPEN) return;

    const enc = new TextEncoder();
    if (key === "ctrl-c") {
      ws.send(JSON.stringify({ type: "signal", signal: "interrupt" }));
    } else if (key === "tab") {
      ws.send(enc.encode("\t"));
    } else if (key === "esc") {
      ws.send(enc.encode("\x1b"));
    } else if (key === "up") {
      ws.send(enc.encode("\x1b[A"));
    } else if (key === "down") {
      ws.send(enc.encode("\x1b[B"));
    } else if (key === "left") {
      ws.send(enc.encode("\x1b[D"));
    } else if (key === "right") {
      ws.send(enc.encode("\x1b[C"));
    } else if (key === "ctrl-d") {
      ws.send(enc.encode("\x04"));
    } else if (key === "ctrl-z") {
      ws.send(enc.encode("\x1a"));
    } else if (key === "pageup") {
      ws.send(enc.encode("\x1b[5~"));
    } else if (key === "pagedown") {
      ws.send(enc.encode("\x1b[6~"));
    } else if (key === "home") {
      ws.send(enc.encode("\x1b[H"));
    } else if (key === "end") {
      ws.send(enc.encode("\x1b[F"));
    } else if (key.startsWith("alt-")) {
      const char = key.replace("alt-", "");
      ws.send(enc.encode("\x1b" + char));
    } else if (key.startsWith("ctrl-")) {
      const char = key.replace("ctrl-", "");
      if (char.length === 1) {
        const code = char.toUpperCase().charCodeAt(0) - 64;
        if (code >= 1 && code <= 26) {
          ws.send(new Uint8Array([code]));
        }
      }
    } else {
      ws.send(enc.encode(key));
    }
  };

  return (
    <div ref={rootRef} className="flex flex-col h-[100dvh] bg-terminal text-foreground overflow-hidden">
      {/* High-polish Orca Topbar */}
