      sessions: [
        { sessionId: "s1", workspaceId: "proj-inactive", worktreeLabel: "feature/x", running: true },
        { sessionId: "s2", workspaceId: "proj-inactive", worktreeLabel: "feature/y", running: true },
      ],
      projects: [{ workspaceId: "proj-active" }, { workspaceId: "proj-inactive" }],
      activeWorkspaceId: "proj-active",
