      sessions: [
        { sessionId: "s1", workspaceId: null, worktreeLabel: null, running: true },
        { sessionId: "s2", workspaceId: "unknown-project", worktreeLabel: "main", running: true },
      ],
      projects: [{ workspaceId: "proj-a" }],
      activeWorkspaceId: "proj-a",
    });

    expect(groups).toHaveLength(1);
    expect(groups[0].isUngrouped).toBe(true);
    expect(groups[0].label).toBe("Ungrouped");
    const sessionIds = groups[0].worktreeGroups.flatMap((wg) => wg.sessions.map((s) => s.sessionId));
    expect(sessionIds.sort()).toEqual(["s1", "s2"]);
  });

  it("buildHierarchy handles sessions-only mode with no project metadata at all", () => {
    const groups = buildHierarchy({
      sessions: [{ sessionId: "s1", running: true }],
    });

    expect(groups).toHaveLength(1);
    expect(groups[0].isUngrouped).toBe(true);
    expect(groups[0].worktreeGroups).toHaveLength(1);
    expect(groups[0].worktreeGroups[0].label).toBe("Ungrouped");
  });

  it("RemoteSessionList renders accessible accordion toggles with aria-expanded that collapse on click", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();

    render(
      <RemoteSessionList
        sessions={[
          { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: "main", running: true },
          { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: "main", running: true },
        ]}
        projects={[{ workspaceId: "proj-a" }, { workspaceId: "proj-b" }]}
