        onRefresh={handleRefresh}
      />
    );

    const projectToggles = screen.getAllByRole("button", { expanded: true }).filter((btn) =>
      /proj-a|proj-b/.test(btn.textContent || "")
    );
    expect(projectToggles.length).toBeGreaterThanOrEqual(2);

    const toggle = projectToggles[0];
    expect(toggle).toHaveAttribute("aria-expanded", "true");
